import{_ as t,o as s,c as o,a0 as i}from"./chunks/framework.ChlVJx0I.js";const a="/pi-extensions/assets/resources.iPsf5OSn.png",u=JSON.parse('{"title":"resource-toggle extension","description":"","frontmatter":{},"headers":[],"relativePath":"extensions/resource-toggle.md","filePath":"extensions/resource-toggle.md","lastUpdated":1791312686000}'),r={name:"extensions/resource-toggle.md"};function n(l,e,c,d,h,g){return s(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="resource-toggle-extension" tabindex="-1">resource-toggle extension <a class="header-anchor" href="#resource-toggle-extension" aria-label="Permalink to &quot;resource-toggle extension&quot;">​</a></h1><p>Enable and disable extensions, skills, prompt templates, and themes from inside a running session, without editing settings files by hand.</p><ul><li><code>/resources</code> opens the interactive list in TUI mode (a text table in the headless modes).</li><li><code>/enable &lt;name&gt;</code>, <code>/disable &lt;name&gt;</code>, and <code>/inherit &lt;name&gt;</code> change the state of one named resource; <code>--project</code> selects project mode, <code>--global</code> is the default.</li><li>A state command with no name opens the resource picker in TUI mode: a searchable single-pick list of every resource, filterable by name, path, or kind. A pick applies the toggle of that command in the active mode and closes on success; a no-op pick, a single-file package refusal, or a self-guard refusal says why and keeps the picker open. In RPC and print modes the command prints the resource table instead.</li><li>While typing a state command, matching display names autocomplete inline, each with the resource&#39;s description.</li><li>The <code>resource_toggle</code> tool lets the agent list resources and apply changes on request; with no arguments it opens the interactive list, and an action without a name relays the no-argument command, so the picker opens for the user.</li></ul><p>State lives in pi&#39;s native settings override patterns - the same files and the same format <code>pi config</code> uses (<a href="/pi-extensions/adr/0012-resource-toggles-write-native-settings-patterns.html">ADR 0012</a>). The commands and <code>pi config</code> are interchangeable: a change made in one shows up in the other.</p><h2 id="screenshot" tabindex="-1">Screenshot <a class="header-anchor" href="#screenshot" aria-label="Permalink to &quot;Screenshot&quot;">​</a></h2><p>The interactive list with the fixture resource set, grouped by type. The checkbox shows the state in the current mode; the <code>usage</code> extension is disabled by a settings pattern, so its box is empty. The dimmed line under a resource is its description, derived from the source file.</p><p><img src="'+a+'" alt="resource list TUI"></p><h2 id="behavior" tabindex="-1">Behavior <a class="header-anchor" href="#behavior" aria-label="Permalink to &quot;Behavior&quot;">​</a></h2><ul><li><strong>Write modes.</strong> Global mode writes the global settings (<code>&lt;agent dir&gt;/settings.json</code>); project mode writes the project settings (<code>&lt;cwd&gt;/.pi/settings.json</code>). A project resource can be overridden in project mode; <code>inherit</code> clears that override so the resource returns to the global state. <code>inherit</code> has no global mode.</li><li><strong>Immediate effect.</strong> Every change flushes the settings and reloads the session, so the change applies at once and survives a restart. The reload rebinds every extension, so the in-session state of other extensions resets.</li><li><strong>Self-guard.</strong> The extension refuses to disable or clear itself: doing so would remove the toggle commands from the session.</li><li><strong>Name matching.</strong> A name may be a display name, a unique name prefix, or a path fragment. A name that matches several resources is reported as ambiguous with the candidates listed, each with its description; a name that matches none is reported as not found.</li><li><strong>Package resources.</strong> A resource bundled in a package is toggled by a filter in the packages array of the settings (<a href="/pi-extensions/adr/0029-package-toggles-write-packages-array-filters.html">ADR 0029</a>), not by a resource-array pattern. A local source is rewritten relative to the project directory so the project file stays portable. Toggling a resource from a single-file package source is refused with a clear message: pi loads a single-file source unconditionally, so its state cannot be toggled.</li><li><strong>Descriptions.</strong> The one-line description of a resource is derived from its source file at list time, never stored: the skill <code>SKILL.md</code> frontmatter <code>description</code>, the prompt template frontmatter <code>description</code> falling back to the first non-empty line, and the leading block comment of an extension entry file (a BOM or shebang line may precede it). The description shows in the picker, the completion list, the interactive list, the headless table, and the ambiguous-name candidates; it is capped at 60 characters in the table, and themes have no description.</li><li><strong>Trusted projects only.</strong> Project mode requires a trusted project; in an untrusted project the TUI shows the restriction and project commands are refused.</li><li><strong>Headless modes.</strong> In print and RPC modes <code>/resources</code> prints the table and the state commands work with a console report; the interactive list is TUI mode only.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of scope&quot;">​</a></h2><ul><li>Installing or removing resources (enabling and disabling only).</li><li>Per-session (non-persisted) toggles: every change is written to settings.</li><li>Toggling pi&#39;s built-in tools. The <a href="/pi-extensions/extensions/tools.html">tools extension</a> covers built-in tools.</li></ul><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><ul><li><code>tests/resource-toggle/matcher.test.ts</code> - name matching, ambiguity, and the argument-completion items.</li><li><code>tests/resource-toggle/resolver.test.ts</code> - resource discovery across scopes and the description derivation per resource kind.</li><li><code>tests/resource-toggle/state-machine.test.ts</code> - the pattern transitions for enable, disable, and inherit in both write modes.</li><li><code>tests/resource-toggle/tui.test.ts</code> - the interactive list rendering.</li><li><code>npm run e2e:resource-toggle</code> - a real pi RPC session: list, toggle, reload, the self-guard, the packages-array filter cycle (including the self-heal and a tilde-spelled local source), the single-file refusal, the no-name resource table, and the tool relay of a no-name action.</li></ul>',13)])])}const m=t(r,[["render",n]]);export{u as __pageData,m as default};
